@EventHandler( payloadType=RemoveRoomsFromFloorEvent.class)
public void handle( RemoveRoomsFromFloorEvent event) {
    LOGGER.info("handling RemoveRoomsFromFloorEvent - " + event );

    Floor entity = removeFromRooms(event.getFloorId(), event.getRemoveFrom() );
    
	// ------------------------------------------
	// emit to subscribers that find one
	// ------------------------------------------    	
    emitFindFloor( entity );

	// ------------------------------------------
	// emit to subscribers that find all
	// ------------------------------------------    	
    emitFindAllFloor( entity );
}



    /**
     * Method to retrieve the Floor via an FloorPrimaryKey.
     * @param 	id Long
     * @return 	Floor
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Floor handle( FindFloorQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getFloorId() );
    }
    
    /**
     * Method to retrieve a collection of all Floors
     *
     * @param	query	FindAllFloorQuery 
     * @return 	List<Floor> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Floor> handle( FindAllFloorQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindFloor,
 * but only if the id matches
 *
 * @param		entity	Floor
 */
	protected void emitFindFloor( Floor entity ) {
		LOGGER.info("handling emitFindFloor" );
		
	    queryUpdateEmitter.emit(FindFloorQuery.class,
	                            query -> query.getFilter().getFloorId().equals(entity.getFloorId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllFloor
	 * 
	 * @param		entity	Floor
	 */
	protected void emitFindAllFloor( Floor entity ) {
		LOGGER.info("handling emitFindAllFloor" );
		
	    queryUpdateEmitter.emit(FindAllFloorQuery.class,
	                            query -> true,
	                            entity);
	}

